import java.io.*;
import java.util.*;

public class J implements Runnable {

    private static final boolean ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null;

    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer = new StringTokenizer("");

    private void setup() throws FileNotFoundException {
        Locale.setDefault(Locale.US);
        String filename = "";
        if (ONLINE_JUDGE && filename.isEmpty()) {
            reader = new BufferedReader(new InputStreamReader(System.in));
            writer = new PrintWriter(System.out);
        } else {
            if (filename.isEmpty()) {
                reader = new BufferedReader(new FileReader("input.txt"));
                writer = new PrintWriter(new FileWriter("output.txt"));
            } else {
                reader = new BufferedReader(new FileReader(filename + ".in"));
                writer = new PrintWriter(new FileWriter(filename + ".out"));
            }
        }
    }

    String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    int[] readInts(int size) throws IOException {
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    public static void main(String[] args) {
        new J().run();
    }

    long start, end;

    void measure() {
        end = System.currentTimeMillis();
        System.err.println("Time: " + (end - start));
    }

    @Override
    public void run() {
        try {
            start = System.currentTimeMillis();
            setup();
            process();
            writer.close();
            measure();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(-1);
        }
    }

    int[][][][] dp;
    char[] arr;
    int INF = 10000000;

    int getCost(char[] s, char target, int v, int k, int x) {
        int res = 0;
        for (char c : s) {
            if (c == 'V') {
                v--;
                if (v == 0 && target == 'V') return res;
                if (v < 0) res++;
            }
            if (c == 'K') {
                k--;
                if (k == 0 && target == 'K') return res;
                if (k < 0) res++;
            }
            if (c == 'X') {
                x--;
                if (x == 0 && target == 'X') return res;
                if (x < 0) res++;
            }
        }
        throw new RuntimeException();
    }

    private void process() throws IOException {
        int n = nextInt();
        arr = next().toCharArray();
        int vCount = 0, kCount = 0, xCount = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == 'V') vCount++;
            else if (arr[i] == 'K') kCount++;
            else {
                arr[i] = 'X';
                xCount++;
            }
        }
        dp = new int[vCount + 1][kCount + 1][xCount + 1][3];
        for (int[][][] layer : dp) {
            for (int[][] row : layer) {
                for (int[] col : row) {
                    Arrays.fill(col, INF);
                }
            }
        }
        for (int i = 0; i < 3; i++) {
            dp[0][0][0][i] = 0;
        }
        for (int v = 0; v <= vCount; v++) {
            for (int k = 0; k <= kCount; k++) {
                for (int x = 0; x <= xCount; x++) {
                    for (int prevState = 0; prevState < 3; prevState++) {
                        int current = dp[v][k][x][prevState];
                        if (current == INF) continue;
                        if (v + 1 <= vCount) {
                            int cst = getCost(arr, 'V', v + 1, k, x);
                            dp[v + 1][k][x][0] = Math.min(dp[v + 1][k][x][0], current + cst);
                        }
                        if (k + 1 <= kCount) {
                            int cst = getCost(arr, 'K', v, k + 1, x);
                            if (prevState != 0) {
                                dp[v][k + 1][x][1] = Math.min(dp[v][k + 1][x][1], current + cst);
                            }
                        }
                        if (x + 1 <= xCount) {
                            int cst = getCost(arr, 'X', v, k, x + 1);
                            dp[v][k][x + 1][2] = Math.min(dp[v][k][x + 1][2], current + cst);
                        }
                    }
                }
            }
        }
        int answer = INF;
        for (int i = 0; i < 3; i++) {
            answer = Math.min(answer, dp[vCount][kCount][xCount][i]);
        }
        System.out.println(answer);
    }
}
