import sys
import math

def main():
    INF = 10**7
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    arr = list(data[1])
    vCount = 0
    kCount = 0
    xCount = 0
    for i in range(len(arr)):
        if arr[i] == 'V':
            vCount += 1
        elif arr[i] == 'K':
            kCount += 1
        else:
            arr[i] = 'X'
            xCount += 1

    # Initialize DP array
    dp = [[[[INF for _ in range(3)] for _ in range(xCount + 1)] for _ in range(kCount + 1)] for _ in range(vCount + 1)]
    for i in range(3):
        dp[0][0][0][i] = 0

    def getCost(s, target, v, k, x):
        res = 0
        for c in s:
            if c == 'V':
                v -= 1
                if v == 0 and target == 'V':
                    return res
                if v < 0:
                    res += 1
            elif c == 'K':
                k -= 1
                if k == 0 and target == 'K':
                    return res
                if k < 0:
                    res += 1
            elif c == 'X':
                x -= 1
                if x == 0 and target == 'X':
                    return res
                if x < 0:
                    res += 1
        raise RuntimeError()

    for v in range(vCount + 1):
        for k in range(kCount + 1):
            for x in range(xCount + 1):
                for prevState in range(3):
                    current = dp[v][k][x][prevState]
                    if current == INF:
                        continue
                    if v + 1 <= vCount:
                        cst = getCost(arr, 'V', v + 1, k, x)
                        if dp[v + 1][k][x][0] > current + cst:
                            dp[v + 1][k][x][0] = current + cst
                    if k + 1 <= kCount:
                        cst = getCost(arr, 'K', v, k + 1, x)
                        if prevState != 0 and dp[v][k + 1][x][1] > current + cst:
                            dp[v][k + 1][x][1] = current + cst
                    if x + 1 <= xCount:
                        cst = getCost(arr, 'X', v, k, x + 1)
                        if dp[v][k][x + 1][2] > current + cst:
                            dp[v][k][x + 1][2] = current + cst

    answer = min(dp[vCount][kCount][xCount])
    print(answer)

